"""Independent #557 generated bytes, with immutable parent geometry test helpers."""
import hashlib
import json
import math
from pathlib import Path
import runpy
import sys

PARENT=Path(__file__).with_name('read-rectangle-extrusion-ocp.py')
parent=runpy.run_path(str(PARENT));h=parent['h'];require=parent['require']


def main():
    output=Path(sys.argv[1]).resolve();mode=sys.argv[2] if len(sys.argv)>2 else ''
    require(mode in ('','--bad-pointer','--changed-face','--changed-dimension','--reversed-footprint'),'Unknown rectangle feature control')
    manifest=json.loads((output/'manifest.json').read_text());require(len(manifest['fixtures'])==8,'Initial/edited/reopened/signedzero fixture set required');results=[]
    for index,fixture in enumerate(manifest['fixtures']):
        require(fixture['documentFormat']=='barocss-axis-rectangle-feature' and fixture['documentVersion']==0
                and fixture['sourceVersion']==2 and fixture['geometryVersion']==0,'Feature document/source/native versions changed')
        for key,relative in fixture['files'].items():
            filename=(output/relative).resolve();require(filename.is_relative_to(output),'Feature evidence path escaped')
            require(hashlib.sha256(filename.read_bytes()).hexdigest()==fixture['hashes'][key],'Feature original '+key+' hash mismatch')
        saved=output/fixture['files']['document'];document=json.loads(saved.read_text(),parse_int=float)
        require(hashlib.sha256(saved.read_bytes()).hexdigest()==fixture['serializedSHA256'],'Actual self-produced authoring JSON changed')
        require(set(document)=={'format','version','id','lengthUnit','parameters','profile','feature'},'Serialized document must contain authoring data alone')
        require([p['id'] for p in document['parameters']]==['_rect_ox','_rect_oy','_rect_w','_rect_h','_rect_d'],'Serialized parameter references changed')
        zero_bits=[math.copysign(1,p['valueMM'])<0 and p['valueMM']==0 for p in document['parameters'][:2]]
        require(zero_bits==fixture['signedZeroOrigins'],'Serialized signedzero intent changed')
        table={p['id']:p['valueMM'] for p in document['parameters']};profile=document['profile'];feature=document['feature'];bindings=fixture['bindings']
        require(bindings=={'documentId':document['id'],'featureId':feature['id'],'inputProfileId':profile['id'],'outputBodyId':feature['bodyId'],'parameterIds':{'originX':profile['originX'],'originY':profile['originY'],'width':profile['width'],'height':profile['height'],'distance':feature['distance']}},'Feature authoring ID association changed')
        require(fixture['origin']==[table[profile['originX']],table[profile['originY']],0] and fixture['sides']==[table[profile['width']],table[profile['height']],table[feature['distance']]],'Feature authoring parameters differ from regenerated geometry request')
        filename=output/fixture['files']['iges'];mappings=fixture['exportReport']['objects'];require(parent['pointers'](filename,mappings),'Rectangle feature load comparison failed: original DE mapping')
        require([m['id'] for m in mappings]==[o['id'] for o in fixture['model']['objects']],'Feature actual selected ID mapping changed')
        reader,adapters,shapes,structure=parent['load'](filename);checked=parent['geometry'](adapters,shapes,fixture);associations=parent['footprint'](adapters[0],fixture)
        if mode and index==0:
            if mode=='--reversed-footprint':
                (output/'reversed-footprint-observed.json').write_text(json.dumps(structure,indent=2)+'\n');parent['footprint'](adapters[0],fixture,True)
            else:
                control=json.loads((output/'negative-files.json').read_text())[mode[2:]];changed=(output/control['file']).resolve()
                require(changed.is_relative_to(output) and hashlib.sha256(changed.read_bytes()).hexdigest()==control['sha256'] and control['originalSHA256']==fixture['hashes']['iges'],'Feature control byte lineage mismatch')
                if mode=='--bad-pointer':
                    changed_reader=h['IGESControl_Reader']();status=changed_reader.ReadFile(str(changed));observed={'readStatus':str(status),'loadDiagnostics':h['diagnostics'](changed_reader.WS().ModelCheckList(True)),'pointerValid':parent['pointers'](changed,mappings)};(output/'bad-pointer-observed.json').write_text(json.dumps(observed,indent=2)+'\n');require(observed['pointerValid'],'Rectangle feature load comparison failed: corrupted directory pointer')
                else:
                    require(parent['pointers'](changed,mappings),'Readable feature corruption must preserve pointers');_,altered,altered_shapes,observed=parent['load'](changed);(output/(mode[2:]+'-observed.json')).write_text(json.dumps(observed,indent=2)+'\n');parent['geometry'](altered,altered_shapes,fixture)
            raise AssertionError('Rectangle feature negative unexpectedly passed')
        results.append({'name':fixture['name'],'documentFormat':fixture['documentFormat'],'documentVersion':0,'sourceVersion':2,'geometryVersion':0,'reopened':fixture['reopened'],'bindings':bindings,'serializedSHA256':fixture['serializedSHA256'],'signedZeroOrigins':zero_bits,'mapping':mappings,'structuralRead':structure,'footprintChecks':associations,'hashes':fixture['hashes'],'files':fixture['files'],**checked})
    require(not mode,'Feature negative did not reach comparison')
    for name in ('initial','width8','width8-distance10','signed-zero'):
        original=next(row for row in manifest['fixtures'] if row['name']==name);reopened=next(row for row in manifest['fixtures'] if row['name']==name+'-reopened')
        for key in ('document','source','ir','model','profile','faces','shell','solidReport','construction','iges','exportReport'):
            require(original['hashes'][key]==reopened['hashes'][key],'Reopened feature changed original '+key+' bytes')
    require([next(row for row in results if row['name']==name)['nativeSolidReport']['volumeMM3'] for name in ('initial','width8','width8-distance10')]==[210,240,400],'Feature edit native volume lineage changed')
    report={'base':manifest['base'],'head':manifest['head'],'fixtures':results,'readerDependencies':{PARENT.name:hashlib.sha256(PARENT.read_bytes()).hexdigest(),'read-derivatives-ocp.py':hashlib.sha256(parent['UTIL'].read_bytes()).hexdigest()},'limits':manifest['limits'],'readerSolidConstructed':False,'wholeSolidInterchange':False,'featureHistoryInterchange':False,'scope':'Actual feature document evaluate/edit/self-produced JSON.parse/reopen geometry; original source2/native7-object IGES only.'};(output/'rectangle-feature-readback.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'fixtures':len(results),'entities':len(results)*7,'surfaces':len(results)*6,'surfaceD1Samples':sum(f['sampleCount'] for row in results for f in row['faces']),'footprintSamples':sum(f['sampleCount'] for row in results for f in row['footprintChecks'])}))


if __name__=='__main__':
    try:main()
    except AssertionError as error:
        # Preserve actual parent reader failure details with the child stage name.
        raise AssertionError(str(error).replace('Rectangle extrusion','Rectangle feature')) from error
